IShape[] shapes = { new Rectangle(2, 3), new Square(2) };
foreach (var s in shapes)
    Console.WriteLine($"{s.Name}: {s.Area()}");

public interface IShape
{
    string Name { get; }
    double Area();
}

public class Rectangle(double w, double h) : IShape
{
    public virtual string Name => "Rectangle";
    public double Area() => w * h;
}

public class Square(double side) : Rectangle(side, side)
{
    public override string Name => "Square";
}

IShape good = new GoodSquare(2), bad = new BadSquare(2);
Console.WriteLine(good.Name); // Square
Console.WriteLine(bad.Name);  // Rectangle  <-- "new" hides, it doesn't override

public interface IShape { string Name { get; } double Area(); }
public class Rectangle(double w, double h) : IShape
{
    public virtual string Name => "Rectangle";
    public double Area() => w * h;
}
public class GoodSquare(double s) : Rectangle(s, s) { public override string Name => "Square"; }
public class BadSquare(double s) : Rectangle(s, s) { public new string Name => "Square"; }

